head.script:
// 테스트 설명, 유효성 값 설정 (textarea 전용)
scwin.tData = {
    "description" : "[textarea > P > validator]<br/>Textarea 컴포넌트에서 포커스가 해제될때 입력값 검증을 처리할 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "포커스가 해제될때 실행할 사용자 정의 함수의 이름을 설정합니다.",
        "사용자 정의 함수의 파라미터로 입력값과 대상 컴포넌트의 렌더링 ID 가 전달됩니다.",
        "사용자 정의 함수의 반환값이 새로운 입력값으로 적용됩니다.",
        "사용자 정의 함수가 수행된 후 onblur 이벤트가 발생합니다.",
        "사용자 정의 함수의 반환값으로 입력값이 변경되면 onchange → onviewchange → onblur 순으로 이벤트가 발생합니다.",
        "Textarea 컴포넌트는 enterBlur 속성을 미지원합니다.",
    ]
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// textarea 는 enterBlur 속성 미지원 → 공통 wframe 의 con_enterBlur 콤보 비활성화 + textarea 전용 description/validation 으로 덮어쓰기
scwin.wf_sample_onwframeload = function () {
    if (wf_sample.getObj("con_enterBlur")) {
        wf_sample.getObj("con_enterBlur").setDisabled(true);
    }

    setTimeout(function () {
        wf_sample.getObj("wf_body_left").getObj("scwin").createValidation(scwin.tData);
    }, 300);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        validator : wf_sample.getObj("con_validator").getText(),
    }

    let cList = $c.gcm.createCList(properties)

    let eList = $c.gcm.createEList(["onchange", "onviewchange", "onblur"]);

    // comp 생성 함수 호출
    $c.gcm.createBasicTextArea(cList, eList);
}
